robe-reload')){'[team-wire-process] reload-passed'}elseif($Phase -in @('team-wire-regular','team-wire-wardrobe')){'[team-wire-process] invitation-passed'}elseif($Phase -eq 'team-wire-reload'){'[team-wire-process] reload-passed'}elseif($Phase -eq 'team-wire'){'[team-wire-process] invitation-passed'}elseif($Phase -like 'anniv-*'){'[anniv-process] '+$Phase+'-passed'}elseif($Phase -like 'clan-*'){'[clan-process] '+$Phase+'-passed'}elseif($Phase -like 'ctf-*'){'[ctf-process] '+$Phase+'-passed'}elseif($Phase -like 'flower-*'){'[flower-process] '+$Phase+'-passed'}elseif($Phase -like 'beast-*'){'[beast-process] '+$Phase+'-passed'}elseif($Phase -like 'elite-*'){'[elite-guild-process] '+$Phase+'-passed'}elseif($Phase -like 'super-*'){'[super-process] '+$Phase+'-passed'}elseif($Phase -like 'pirate-*'){'[pirate-process] '+$Phase+'-passed'}elseif($Phase -like 'taoist-*'){'[taoist-process] '+$Phase+'-passed'}elseif($Phase -like 'mastery-*'){'[mastery-process] '+$Phase+'-passed'}elseif($Phase -like 'guild-*'){'[guild-process] '+$Phase+'-passed'}elseif($Phase -like 'monk-*'){'[monk-process] '+$Phase+'-passed'}elseif($Phase -like 'ninja-*'){'[ninja-process] '+$Phase+'-passed'}elseif($Phase -like 'warrior-*'){'[warrior-process] '+$Phase+'-passed'}elseif($Phase -like 'trojan-*'){'[trojan-process] '+$Phase+'-passed'}elseif($Phase -like 'mount-*'){'[mount-process] '+$Phase+'-passed'}elseif($Phase -like 'fan-*'){'[fan-process] '+$Phase+'-passed'}elseif($Phase -like 'tower-*'){'[tower-process] '+$Phase+'-passed'}elseif($Phase -like 'fashion-*'){'[fashion-process] '+$Phase+'-passed'}elseif($Phase -like 'planet-*'){'[planet-process] '+$Phase+'-passed'}elseif($Phase -like 'heart-*'){'[heart-process] '+$Phase+'-passed'}elseif($Phase -like 'tempest-*'){'[tempest-process] '+$Phase+'-passed'}elseif($Phase -like 'elimination-*'){'[elimination-process] '+$Phase+'-passed'}elseif($Phase -like 'mrms-*'){'[mrms-process] '+$Phase+'-passed'}elseif($Phase -eq 'team'){'[arena-process] team-leader-and-member-earned-rewards-persisted'}elseif($Phase -eq 'spend'){'[arena-process] twenty-earned-matches-honor-purchase-persisted'}else{'[arena-process] recovered-five-ordinary-fixtures-without-replay'}
    if($child.ExitCode -ne 0 -or !$result.Contains($marker)){throw ('Arena lifecycle '+$Phase+' failed; inspect its redacted log.')}
    Write-Output ('Arena lifecycle '+$Phase+' passed; game SHA256 '+(Get-FileHash -LiteralPath (Join-Path $output 'Revora.exe')).Hash)
} finally {
    if($started -and !$child.HasExited){$child.Kill();$child.WaitForExit()}
    [IO.File]::WriteAllBytes($config,$original)
    if((Get-FileHash -LiteralPath $config).Hash -ne $originalHash){throw 'Candidate configuration restoration failed.'}
    foreach($target in $towerCreated) {
        if((Get-FileHash -LiteralPath $target).Hash -ne $towerHash){throw 'Changed temporary Tower terrain retained for inspection.'}
        Remove-Item -LiteralPath $target
    }
    if($tempestCreated) {
        if((Get-FileHash -LiteralPath $tempestTarget).Hash -ne $tempestHash){throw 'Changed temporary Tempest terrain retained for inspection.'}
        Remove-Item -LiteralPath $tempestTarget
    }
    $start.EnvironmentVariables.Remove('REVORA_DATABASE_PASSWORD');$credential=$null;$secure.Dispose();$child.Dispose()
}
